changes_description:
Change 1: Replace:
  def priority(item, bins):
      """Penalize tight and very loose slack to encourage moderate residual capacity."""
      slack = bins - item
      return -slack - 5.0 * np.exp(-slack / 3.0) - 0.05 * slack**2
with:
  def priority(item, bins):
      """Penalize tight slack to avoid fragmentation; prefer moderate residual capacity."""
      slack = bins - item
      return -slack - 5.0 * np.exp(-slack / 3.0)

